<!DOCTYPE html>
<html>
<head>
<title>Simple Desktop Environment</title>
<style>
body {
  background-color: #2e3440; /* Dark theme */
  margin: 0;
  font-family: sans-serif;
}

#desktop {
  width: 100%;
  height: 100vh;
  display: grid;
  grid-template-rows: auto 1fr; /* Taskbar at the top, desktop below */
}

#taskbar {
  background-color: #434c5e;
  color: white;
  padding: 10px;
  text-align: left;
}

#taskbar button {
  background-color: transparent;
  border: none;
  color: white;
  cursor: pointer;
  padding: 5px 10px;
}

#taskbar #open-files {
  margin-right: 20px;
}

.window {
  position: absolute;
  top: 0;
  left: 0;
  width: 360px; /* Minimum window size */
  height: 240px; /* Minimum window size */
  background-color: #2e3440;
  border: 1px solid #434c5e;
  display: flex;
  flex-direction: column;
}

.window .close {
  position: absolute;
  top: 5px;
  right: 5px;
  background-color: #dc3545; /* Red close button */
  color: white;
  border: none;
  padding: 5px 10px;
  cursor: pointer;
}

.fs-item {
  margin: 2px;
  padding: 2px;
  background-color: #434c5e;
  color: white;
  border-radius: 3px;
  cursor: pointer;
}

.fs-item:hover {
  background-color: #596071;
}

#files-path {
  margin: 5px;
  color: white;
}

#files-window {
  position: absolute;
  top: 0;
  left: 360px;
  width: 360px;
  height: 240px;
  background-color: #2e3440;
  border: 1px solid #434c5e;
}

#notepad-window {
    position: absolute;
    top: 0;
    left: 360px;
    width: 360px;
    height: 240px;
    background-color: #2e3440;
    border: 1px solid #434c5e;
}

#tabs {
  display: flex;
}

.tab {
  background-color: #434c5e;
  color: white;
  padding: 8px 12px;
  cursor: pointer;
  border: none;
  margin-right: 5px;
}

.tab:hover {
  background-color: #596071;
}

#editor {
  width: 100%;
  height: 80%;
  padding: 10px;
  border: none;
  font-family: monospace;
}
</style>
</head>
<body>

<div id="desktop">
  <div id="taskbar">
    <button id="open-files">Files</button>
    <button id="open-notepad">Notepad</button>
  </div>
  <div id="files-path">/</div>
  <ul id="files-list">
    <li class="fs-item" data-path="/">bin</li>
    <li class="fs-item" data-path="/etc">etc</li>
    <li class="fs-item" data-path="/home">home</li>
    <li class="fs-item" data-path="/usr">usr</li>
    <li class="fs-item" data-path="/var">var</li>
    <li class="fs-item" data-path="/home/user">
      <span class="fs-item">Documents</span>
      <span class="fs-item">Downloads</span>
      <span class="fs-item">Pictures</span>
    </li>
  </ul>
  <div id="files-up"></div>

  <div id="tabs">
    <button class="tab" data-tab="new">New Tab</button>
  </div>
  <div id="editor" contenteditable="true"></div>
  <div id="new-tab"></div>
  <div id="notepad-window"></div>

</div>

<script>
const desktop = document.getElementById('desktop');
const taskbar = document.getElementById('taskbar');
const openFilesButton = document.getElementById('open-files');
const openNotepadButton = document.getElementById('open-notepad');
const filesPathDisplay = document.getElementById('files-path');
const filesList = document.getElementById('files-list');
const filesUpButton = document.getElementById('files-up');
const tabs = document.getElementById('tabs');
const newTabButton = document.getElementById('new-tab');
const editor = document.getElementById('editor');
const notepadWindow = document.getElementById('notepad-window');

let currentPath = '/';
let tabsContainer = document.createElement('div');
let tabContent = document.createElement('div');
let currentTab = 0;


function updateFilesPath() {
    filesPathDisplay.textContent = currentPath;
}

function openFilesWindow() {
    const filesWindow = document.getElementById('files-window');
    filesWindow.innerHTML = ''; // Clear previous content
    populateFilesList(currentPath);
    desktop.style.gridTemplateRows = 'auto 1fr';
    openFilesButton.disabled = true;

}

function openNotepadWindow() {
    notepadWindow.innerHTML = '';
    const tabStrip = document.createElement('div');
    tabStrip.id = 'tabs';
    const newTab = document.createElement('button');
    newTab.classList.add('tab');
    newTab.textContent = 'New Tab';
    newTab.addEventListener('click', () => {
        createTab();
    });
    tabStrip.appendChild(newTab);

    const editorDiv = document.createElement('div');
    editorDiv.id = 'editor';
    editorDiv.contentEditable = true;

    notepadWindow.appendChild(tabStrip);
    notepadWindow.appendChild(editorDiv);

    openNotepadButton.disabled = true;

}


function createTab() {
    const newTabElement = document.createElement('button');
    newTabElement.classList.add('tab');
    newTabElement.textContent = 'New Tab';
    tabs.appendChild(newTabElement);

    // Create a new content div for the tab
    const newEditorDiv = document.createElement('div');
    newEditorDiv.id = 'editor';
    newEditorDiv.contentEditable = true;
    newEditorDiv.style.display = 'none'; // Initially hidden
    tabsContainer.appendChild(newEditorDiv);

}


function populateFilesList(path) {
  filesList.innerHTML = '';
  const items = [
      { name: 'bin', type: 'directory' },
      { name: 'etc', type: 'directory' },
      { name: 'home', type: 'directory' },
      { name: 'usr', type: 'directory' },
      { name: 'var', type: 'directory' },
      { name: 'document.txt', type: 'file' }
  ];

  items.forEach(item => {
    const listItem = document.createElement('li');
    listItem.classList.add('fs-item');
    listItem.dataset.path = path + '/' + item.name;
    listItem.textContent = item.name;

    if (item.type === 'directory') {
      listItem.addEventListener('click', () => {
        currentPath = listItem.dataset.path;
        updateFilesPath();
        populateFilesList(currentPath);
      });
    }

    filesList.appendChild(listItem);
  });
}



openFilesButton.addEventListener('click', openFilesWindow);
openNotepadButton.addEventListener('click', openNotepadWindow);


// localStorage persistence for notepad
window.onStorage = () => {
    localStorage.setItem("notepadTabs", JSON.stringify(tabsContainer.children));
    localStorage.removeItem("notepadTabs"); //clear to force reload of tabs
};

if (localStorage.getItem('notepadTabs')) {
  const savedTabs = JSON.parse(localStorage.getItem('notepadTabs'));
  savedTabs.forEach(tab => {
      //create a new tab and append the content of existing tab to it
  });
}

</script>

</body>
</html>
